css:
.dock-stage {
  display: flex;
  align-items: center;
  justify-content: center;
  height: 100%;
  width: 100%;
  overflow: hidden;
  margin: 0;
}

.dock,
.dock * {
  box-sizing: border-box;
}

.dock {
  --s: 64px;
  --max: 1.8;
  --gap: max(4px, calc(var(--s) * 0.08));
  --pad: max(8px, calc(var(--s) * 0.12));

  display: inline-flex;

  padding: var(--pad) calc(var(--pad) - var(--gap) / 2);

  background: linear-gradient(
      180deg,
      rgba(255, 255, 255, 0.13),
      rgba(255, 255, 255, 0.05)
    ),
    rgba(45, 45, 45, 0.75);

  -webkit-backdrop-filter: blur(20px) saturate(150%);
  backdrop-filter: blur(20px) saturate(150%);

  border: 1px solid rgba(255, 255, 255, 0.15);

  border-radius: max(12px, calc(var(--s) * 0.4));

  box-shadow:
    0 max(4px, calc(var(--s) * 0.1)) max(16px, calc(var(--s) * 0.4))
      rgba(0, 0, 0, 0.4),
    0 max(2px, calc(var(--s) * 0.05)) max(8px, calc(var(--s) * 0.2))
      rgba(0, 0, 0, 0.3),
    inset 0 1px 0 rgba(255, 255, 255, 0.15),
    inset 0 -1px 0 rgba(0, 0, 0, 0.2);

  isolation: isolate;
}

.dock::before {
  content: "";

  position: absolute;

  top: 1px;
  left: 1px;
  right: 1px;

  height: 45%;

  border-radius: max(11px, calc(var(--s) * 0.38))
    max(11px, calc(var(--s) * 0.38)) 45% 45%;

  background: linear-gradient(
    180deg,
    rgba(255, 255, 255, 0.12),
    rgba(255, 255, 255, 0)
  );

  pointer-events: none;
  z-index: -1;
}

.dock__row {
  display: flex;
  align-items: flex-end;

  height: var(--s);
  width: 100%;
}

.dock__item {
  --k: 1;

  --shadow-y: max(1px, calc(var(--s) * 0.03));

  --shadow-b: max(2px, calc(var(--s) * 0.06));

  position: relative;

  flex: none;

  display: flex;
  align-items: flex-end;
  justify-content: center;

  width: calc(var(--s) * var(--k) + var(--gap));

  height: calc(var(--s) * var(--k));

  padding: 0 calc(var(--gap) / 2);

  cursor: pointer;

  z-index: 10;

  transform-origin: bottom center;

  transition:
    width 0.2s ease-out,
    height 0.2s ease-out,
    transform 0.2s ease-out;
}

.dock__item input {
  display: none;
}

.dock__item svg {
  display: block;

  width: 100%;
  height: 100%;

  padding: 10%;

  filter: drop-shadow(
    0 var(--shadow-y) var(--shadow-b)
      rgba(0, 0, 0, calc(0.2 + (var(--k) - 1) * 0.15))
  );

  transition: filter 0.2s ease-out;
}

.dock__item:hover {
  --k: var(--max);

  z-index: 18;
}

.dock__item:hover + .dock__item,
.dock__item:has(+ .dock__item:hover) {
  --k: calc(1 + (var(--max) - 1) * 0.56);

  z-index: 15;
}

.dock__item:hover + .dock__item + .dock__item,
.dock__item:has(+ .dock__item + .dock__item:hover) {
  --k: calc(1 + (var(--max) - 1) * 0.05);
}

.dock__item:hover,
.dock__item:hover + .dock__item,
.dock__item:has(+ .dock__item:hover) {
  --shadow-y: max(2px, calc(var(--s) * 0.05));

  --shadow-b: max(4px, calc(var(--s) * 0.1));
}

.dock__item:active {
  transform: translateY(max(-8px, calc(var(--s) * -0.15)));

  transition-duration: 0.2s;
}

.dock__dot {
  display: none;

  position: absolute;

  bottom: max(-2px, calc(var(--s) * -0.05));

  left: 50%;

  transform: translateX(-50%);

  width: max(3px, calc(var(--s) * 0.06));

  height: max(3px, calc(var(--s) * 0.06));

  border-radius: 50%;

  background-color: rgba(255, 255, 255, 0.95);

  box-shadow:
    0 0 5px rgba(255, 255, 255, 0.55),
    0 1px 3px rgba(0, 0, 0, 0.35);
}

.dock__item input:checked ~ .dock__dot {
  display: block;
}

.dock__item input:checked ~ svg {
  filter: drop-shadow(0 2px 3px rgba(0, 0, 0, 0.2))
    drop-shadow(0 8px 12px rgba(0, 0, 0, 0.12));
}

.dock__tooltip {
  position: absolute;

  left: 50%;
  bottom: calc(100% + 14px);

  min-width: max-content;

  transform: translateX(-50%) translateY(6px) scale(0.92);

  transform-origin: bottom center;

  padding: 8px 11px;

  border: 1px solid rgba(255, 255, 255, 0.18);

  border-radius: 9px;

  background: linear-gradient(
      180deg,
      rgba(255, 255, 255, 0.12),
      rgba(255, 255, 255, 0.04)
    ),
    rgba(20, 20, 23, 0.88);

  color: rgba(255, 255, 255, 0.97);

  font-family: -apple-system, BlinkMacSystemFont, "SF Pro Display",
    "SF Pro Text", "Segoe UI", sans-serif;

  font-size: 12px;
  font-weight: 600;

  letter-spacing: 0.01em;
  line-height: 1;

  white-space: nowrap;

  opacity: 0;

  visibility: hidden;

  pointer-events: none;

  box-shadow:
    0 10px 25px rgba(0, 0, 0, 0.28),
    0 2px 8px rgba(0, 0, 0, 0.18),
    inset 0 1px 0 rgba(255, 255, 255, 0.1);

  -webkit-backdrop-filter: blur(18px) saturate(160%);

  backdrop-filter: blur(18px) saturate(160%);

  transition:
    opacity 160ms ease,
    visibility 160ms ease,
    transform 180ms cubic-bezier(0.2, 0.8, 0.2, 1);

  z-index: 100;
}

.dock__item:hover .dock__tooltip {
  opacity: 1;

  visibility: visible;

  transform: translateX(-50%) translateY(0) scale(1);
}

.dock__item:has(input:focus-visible) {
  outline: 2px solid rgba(255, 255, 255, 0.85);

  outline-offset: 3px;

  border-radius: 15px;
}

@media (max-width: 1023px), (max-height: 1023px) {
  .dock {
    --s: 56px;
    --max: 1.6;
  }
}

@media (max-width: 767px), (max-height: 767px) {
  .dock {
    --s: 48px;
    --max: 1.5;
  }
}

@media (max-width: 479px), (max-height: 479px) {
  .dock {
    --s: 40px;
    --max: 1.4;
  }
}

@media (max-width: 767px), (hover: none) {
  .dock__item:hover {
    --k: 1;
  }

  .dock__item:hover + .dock__item,
  .dock__item:has(+ .dock__item:hover) {
    --k: 1;
  }

  .dock__item:hover + .dock__item + .dock__item,
  .dock__item:has(+ .dock__item + .dock__item:hover) {
    --k: 1;
  }

  .dock__tooltip {
    display: none;
  }
}

@media (max-width: 479px) {
  .dock__item svg {
    padding: 8%;
  }
}

@media (prefers-reduced-motion: reduce) {
  .dock,
  .dock__item,
  .dock__item svg,
  .dock__tooltip {
    transition: none !important;
  }
}
